import sys

def main():
    # Read all input from standard input and strip whitespace
    s = sys.stdin.read().strip()
    if not s:
        return

    pairs = {')': '(', ']': '[', '>': '<'}
    stack = []

    for ch in s:
        # If it's an opening bracket, push to stack
        if ch in '([<':
            stack.append(ch)
        # If it's a closing bracket
        else:
            # If stack is empty or top of stack doesn't match the closing bracket
            if not stack or stack[-1] != pairs[ch]:
                print("No")
                return
            # Match found, pop the opening bracket
            stack.pop()

    # If stack is empty, all brackets were matched properly
    print("Yes" if not stack else "No")

if __name__ == "__main__":
    main()
